import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.itemstats.ItemStatPlugin;


@Slf4j
@PluginDescriptor(
	name = "FoodUtils"
)
@PluginDependency(ItemStatPlugin.class)
public class FoodUtilsPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private FoodUtilsConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private FoodHealOverlay foodHealOverlay;

	@Inject
	private PotionOverlay potionOverlay;

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(foodHealOverlay);
		overlayManager.add(potionOverlay);
		log.debug("Food Utils Running");
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(foodHealOverlay);
		overlayManager.remove(potionOverlay);
		log.debug("Food Utils Stopped");
	}

	@Provides
	FoodUtilsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FoodUtilsConfig.class);
	}
}

package com.FoodUtils;

import com.google.inject.Inject;
import javax.inject.Singleton;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import com.FoodUtils.FoodHealRules.*;
import net.runelite.api.Client;
import net.runelite.client.plugins.itemstats.Effect;
import net.runelite.client.plugins.itemstats.ItemStatChangesService;
import net.runelite.client.plugins.itemstats.StatChange;
import net.runelite.client.plugins.itemstats.StatsChanges;
import net.runelite.client.plugins.itemstats.stats.Stats;

@Singleton
public final class FoodData {

    public static final class FoodInfo {
        public final int allowedMaxHp;
        public final int baseHeal;
        public final int effectiveHeal;
        public final int missingToAllowedMax;
        public final int immediateHeal;
        public final int delayedHeal;

        private FoodInfo(int allowedMaxHp, int baseHeal, int effectiveHeal, int missingToAllowedMax, int immediateHeal, int delayedHeal) {
            this.allowedMaxHp = allowedMaxHp;
            this.baseHeal = baseHeal;
            this.effectiveHeal = effectiveHeal;
            this.missingToAllowedMax = missingToAllowedMax;
            this.immediateHeal = immediateHeal;
            this.delayedHeal = delayedHeal;
        }
    }

    private final FoodRuleData foodRuleData;
    private final ItemStatChangesService itemStatChangesService;
    private final Client client;

    @Inject
    public FoodData(FoodRuleData foodRuleData, ItemStatChangesService itemStatChangesService, Client client) {

        this.foodRuleData = foodRuleData;
        this.itemStatChangesService = itemStatChangesService;
        this.client = client;
    }
    // TOA items with mechanics too complex or unique to display correctly — blocked to avoid misleading values
    private static final Set<Integer> BLOCKED_ITEMS = new HashSet<>(Arrays.asList(
            27325, 27323, // Silk dressing (gradual heal over time)
            27351,        // Honey locust (overheal + prayer restore)
            27347, 27349, // Ambrosia (full restore + overheal)
            27315, 27317, 27319, 27321 // Nectar (heals but drains combat stats)
    ));

    // Checks for a manual rule first. Falls back to RuneLite's ItemStatChangesService for standard foods.
    public FoodInfo calculate(int itemId, int baseHp, int currentHP) {
        if (BLOCKED_ITEMS.contains(itemId)) {
            return null;
        }
        HealRule rule = foodRuleData.getRuleForItemId(itemId);
        if (rule != null) {
            return calculateFromRule(rule, baseHp, currentHP);
        }
        return calculateFromItemStats(itemId, baseHp, currentHP);
    }
        // Food with special effects (Overheal, delayed heal) must be delegated to a heal rule and are handled here.
        private FoodInfo calculateFromRule(HealRule rule, int baseHp, int currentHP){
            int allowedMax = rule.allowedMaxHp(baseHp);
            int itemBaseHeal = Math.max(0, rule.itemBaseHealAmount(baseHp));

            if (itemBaseHeal <= 0) {
                return null;
            }

            int missingToAllowedMax = Math.max(0, allowedMax - currentHP);
            int effectiveHeal = Math.min(itemBaseHeal, missingToAllowedMax);

            // Extract immediate/delayed portions if this is a delayed heal rule,
            // otherwise treat the full heal as immediate with no delayed portion.
            int immediateHeal;
            int delayedHeal;
            if (rule instanceof DelayedHealRule)
            {
                DelayedHealRule delayedRule = (DelayedHealRule) rule;
                immediateHeal = delayedRule.immediateHeal;
                delayedHeal = delayedRule.delayedHeal;
            }
            else
            {
                immediateHeal = itemBaseHeal;
                delayedHeal = 0;
            }

            return new FoodInfo(allowedMax, itemBaseHeal, effectiveHeal, missingToAllowedMax, immediateHeal, delayedHeal);
        }
    private FoodInfo calculateFromItemStats(int itemId, int baseHp, int currentHP)
    {
        Effect effect = itemStatChangesService.getItemStatChanges(itemId);
        if (effect == null)
        {
            return null;
        }
        // RuneLite registers these as multiple HITPOINTS entries, so we sum them all for the true total.
        int healTotal = 0;
        int allowedMax = baseHp;
        int missingToAllowedMax = Math.max(0, allowedMax - currentHP);
        int immediateHeal =0;
        int delayedHeal =0;
        int hitpointEntryCount = 0;

        StatsChanges statsChanges = effect.calculate(client);
        if (statsChanges == null || statsChanges.getStatChanges() == null)
        {
            return null;
        }

        for (StatChange statChange : statsChanges.getStatChanges())
        {
            if (statChange == null)
            {
                continue;
            }

            if (Stats.HITPOINTS.equals(statChange.getStat()))
            {

                int entryHeal = Math.max(0, statChange.getTheoretical());
                if (entryHeal <= 0)
                {
                    continue;
                }
                healTotal = entryHeal + healTotal;
                if(hitpointEntryCount ==0) immediateHeal = entryHeal;
                else delayedHeal = entryHeal;
                hitpointEntryCount++;

            }
        }
        // No HITPOINTS entries found — not a food item.
        if(healTotal == 0) return null;
        int effectiveHeal = Math.min(healTotal, missingToAllowedMax);
        return new FoodInfo(allowedMax, healTotal, effectiveHeal, missingToAllowedMax, immediateHeal, delayedHeal);
    }
}

package com.FoodUtils;

import com.FoodUtils.enums.DelayedDisplayMode;
import net.runelite.api.Skill;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import java.awt.*;
import javax.inject.Inject;
import net.runelite.api.Client;
import com.FoodUtils.enums.MixedConsumableMode;

public class FoodHealOverlay extends WidgetItemOverlay {

    private final FoodUtilsConfig config;
    private final Client client;
    private final FoodData foodData;
    private final PotionData potionData;

    @Inject
    public FoodHealOverlay(Client client, FoodUtilsConfig config, FoodData foodData, PotionData potionData)
    {
        this.config = config;
        this.client = client;
        this.foodData = foodData;
        this.potionData = potionData;
        showOnInventory();
    }

    @Override
    public void renderItemOverlay(java.awt.Graphics2D graphics, int itemId, net.runelite.api.widgets.WidgetItem item)
    {
        if (graphics == null || item == null) return;

        Rectangle bounds = item.getCanvasBounds();
        if (bounds == null) return;

        PotionData.PotionInfo potionInfo = null;
        if (config.showPotions())
        {
            potionInfo = potionData.calculate(itemId);
        }
        if (potionInfo != null && config.mixedConsumableMode() == MixedConsumableMode.BOOST) return;

        int currentHP = client.getBoostedSkillLevel(Skill.HITPOINTS);
        int baseHP = client.getRealSkillLevel(Skill.HITPOINTS);
        FoodData.FoodInfo info = foodData.calculate(itemId, baseHP, currentHP);
        if (info == null) return;

        if (config.onlyShowOnHover())
        {
            net.runelite.api.Point mouse = client.getMouseCanvasPosition();
            if (!bounds.contains(mouse.getX(), mouse.getY())) return;
        }

        Font oldFont = graphics.getFont();
        Font customFont = oldFont.deriveFont((float) config.fontSize());
        graphics.setFont(customFont);
        FontMetrics fm = graphics.getFontMetrics();
        java.awt.Color oldColor = graphics.getColor();

        boolean hasDelayedHeal = info.delayedHeal > 0;
        // Dual multicolor mode draws each heal portion in its own color
        boolean dualMultiColor = hasDelayedHeal
                && config.delayedDisplayMode() == DelayedDisplayMode.DUAL
                && config.multiColorDelayed();

        if (dualMultiColor)
        {
            drawDualMultiColor(graphics, bounds, fm, info);
        }
        else
        {
            drawSingleText(graphics, bounds, fm, info, hasDelayedHeal);
        }

        graphics.setFont(oldFont);
        graphics.setColor(oldColor);
    }

    // Draws immediate and delayed heal portions in separate colors
    private void drawDualMultiColor(Graphics2D graphics, Rectangle bounds, FontMetrics fm, FoodData.FoodInfo info)
    {
        String immText = "+" + info.immediateHeal;
        String delText = "-" + info.delayedHeal;
        int immWidth = fm.stringWidth(immText);
        int totalWidth = immWidth + fm.stringWidth(delText);

        int x = getX(bounds, totalWidth);
        int y = getY(bounds, fm);
        x += config.xOffset();
        y += config.yOffset();

        // Calculate how much of each portion the player can actually receive
        int effectiveImmediate = Math.min(info.immediateHeal, info.missingToAllowedMax);
        int effectiveDelayed = Math.min(info.delayedHeal, Math.max(0, info.missingToAllowedMax - info.immediateHeal));

        Color immColor = getHealColor(effectiveImmediate, info.immediateHeal);
        Color delColor = getHealColor(effectiveDelayed, info.delayedHeal);

        if (config.shadow())
        {
            graphics.setColor(Color.BLACK);
            graphics.drawString(immText, x + 1, y + 1);
            graphics.drawString(delText, x + immWidth + 1, y + 1);
        }
        graphics.setColor(immColor);
        graphics.drawString(immText, x, y);
        graphics.setColor(delColor);
        graphics.drawString(delText, x + immWidth, y);
    }

    private void drawSingleText(Graphics2D graphics, Rectangle bounds, FontMetrics fm, FoodData.FoodInfo info, boolean hasDelayedHeal)
    {
        int base = info.baseHeal;
        int effective = info.effectiveHeal;

        String text;
        if (hasDelayedHeal)
        {
            switch (config.delayedDisplayMode())
            {
                case BASE:
                    text = "+" + info.immediateHeal;
                    break;
                case DELAYED:
                    text = "+" + info.delayedHeal;
                    break;
                case DUAL:
                default:
                    text = "+" + info.immediateHeal + "-" + info.delayedHeal;
                    break;
            }
        }
        else
        {
            switch (config.healDisplayMode())
            {
                case BASE:
                    text = "+" + base;
                    break;
                case EFFECTIVE:
                    text = "+" + effective;
                    break;
                case BOTH:
                default:
                    text = "+" + effective + "/" + base;
                    break;
            }
        }

        int x = getX(bounds, fm.stringWidth(text));
        int y = getY(bounds, fm);
        x += config.xOffset();
        y += config.yOffset();

        Color textColor = config.fullValueColor();
        if (config.colorForWaste())
        {
            if (effective == 0) textColor = config.noHealColor();
            else if (effective < base) textColor = config.wasteColor();
            else textColor = config.fullValueColor();
        }

        if (config.shadow())
        {
            graphics.setColor(Color.BLACK);
            graphics.drawString(text, x + 1, y + 1);
        }
        graphics.setColor(textColor);
        graphics.drawString(text, x, y);
    }

    // Returns the appropriate color based on how much of the heal is effective
    private Color getHealColor(int effective, int base)
    {
        if (!config.colorForWaste()) return config.fullValueColor();
        if (effective == 0) return config.noHealColor();
        if (effective < base) return config.wasteColor();
        return config.fullValueColor();
    }

    private int getX(Rectangle bounds, int textWidth)
    {
        switch (config.textPosition())
        {
            case TOP_LEFT:
            case MIDDLE_LEFT:
            case BOTTOM_LEFT:
                return bounds.x + 2;
            case TOP_RIGHT:
            case MIDDLE_RIGHT:
            case BOTTOM_RIGHT:
            default:
                return bounds.x + bounds.width - textWidth - 2;
        }
    }

    private int getY(Rectangle bounds, FontMetrics fm)
    {
        switch (config.textPosition())
        {
            case TOP_LEFT:
            case TOP_RIGHT:
                return bounds.y + 12;
            case MIDDLE_LEFT:
            case MIDDLE_RIGHT:
                return bounds.y + (bounds.height / 2) + (fm.getAscent() / 2) - 2;
            case BOTTOM_LEFT:
            case BOTTOM_RIGHT:
            default:
                return bounds.y + bounds.height - 2;
        }
    }
}

package com.FoodUtils;

import net.runelite.client.ui.overlay.WidgetItemOverlay;
import java.awt.*;
import javax.inject.Inject;
import net.runelite.api.Client;
import com.FoodUtils.enums.MixedConsumableMode;

public class PotionOverlay extends WidgetItemOverlay {

    private final FoodUtilsConfig config;
    private final Client client;
    private final PotionData potionData;
    private final FoodData foodData;

    @Inject
    public PotionOverlay(Client client, FoodUtilsConfig config, PotionData potionData, FoodData foodData)
    {
        this.config = config;
        this.client = client;
        this.potionData = potionData;
        this.foodData = foodData;
        showOnInventory();
    }

    @Override
    public void renderItemOverlay(java.awt.Graphics2D graphics, int itemId, net.runelite.api.widgets.WidgetItem item)
    {
        if (!config.showPotions()) return;
        if (graphics == null || item == null) return;

        Rectangle bounds = item.getCanvasBounds();
        if (bounds == null) return;

        int currentHP = client.getBoostedSkillLevel(net.runelite.api.Skill.HITPOINTS);
        int baseHP = client.getRealSkillLevel(net.runelite.api.Skill.HITPOINTS);

        FoodData.FoodInfo foodInfo = foodData.calculate(itemId, baseHP, currentHP);
        if (foodInfo != null && config.mixedConsumableMode() == MixedConsumableMode.HEAL) return;

        PotionData.PotionInfo info = potionData.calculate(itemId);
        if (info == null) return;

        int base = info.baseBoost;
        int effective = info.effectiveBoost;

        String text;
        switch (config.healDisplayMode())
        {
            case BASE:
                text = "+" + base;
                break;
            case EFFECTIVE:
                text = "+" + effective;
                break;
            case BOTH:
            default:
                text = "+" + effective + "/" + base;
                break;
        }

        // Gradual potions (e.g. prayer regen) get a ~ prefix and no + sign to indicate they restore over time
        if (info.isGradual)
        {
            switch (config.healDisplayMode())
            {
                case BASE:
                    text = "~" + base;
                    break;
                case EFFECTIVE:
                    text = "~" + effective;
                    break;
                case BOTH:
                default:
                    text = "~" + effective + "/" + base;
                    break;
            }
        }

        if (config.onlyShowOnHover())
        {
            net.runelite.api.Point mouse = client.getMouseCanvasPosition();
            if (!bounds.contains(mouse.getX(), mouse.getY())) return;
        }

        Font oldFont = graphics.getFont();
        Font customFont = oldFont.deriveFont((float) config.fontSize());
        graphics.setFont(customFont);
        FontMetrics fm = graphics.getFontMetrics();

        int x;
        int y;
        switch (config.textPosition())
        {
            case TOP_LEFT:
                x = bounds.x + 2;
                y = bounds.y + 12;
                break;
            case TOP_RIGHT:
                x = bounds.x + bounds.width - fm.stringWidth(text) - 2;
                y = bounds.y + 12;
                break;
            case MIDDLE_LEFT:
                x = bounds.x + 2;
                y = bounds.y + (bounds.height / 2) + (fm.getAscent() / 2) - 2;
                break;
            case MIDDLE_RIGHT:
                x = bounds.x + bounds.width - fm.stringWidth(text) - 2;
                y = bounds.y + (bounds.height / 2) + (fm.getAscent() / 2) - 2;
                break;
            case BOTTOM_LEFT:
                x = bounds.x + 2;
                y = bounds.y + bounds.height - 2;
                break;
            case BOTTOM_RIGHT:
            default:
                x = bounds.x + bounds.width - fm.stringWidth(text) - 2;
                y = bounds.y + bounds.height - 2;
                break;
        }

        x += config.xOffset();
        y += config.yOffset();

        java.awt.Color oldColor = graphics.getColor();
        java.awt.Color textColor;

        // Gradual potions always use the gradual color — waste logic doesn't apply
        if (info.isGradual)
        {
            textColor = config.gradualPotionColor();
        }
        else if (config.colorForWaste())
        {
            if (effective == 0) textColor = config.noHealColor();
            else if (effective < base) textColor = config.wasteColor();
            else textColor = config.fullValueColor();
        }
        else
        {
            textColor = config.fullValueColor();
        }

        if (config.shadow())
        {
            graphics.setColor(java.awt.Color.BLACK);
            graphics.drawString(text, x + 1, y + 1);
        }
        graphics.setColor(textColor);
        graphics.drawString(text, x, y);
        graphics.setFont(oldFont);
        graphics.setColor(oldColor);
    }
}
